// ---- The bug's own paint (outside the animation region) ----
// Copies the NOW word from its hidden source, closes the show row when the show is empty, and
// writes the channel's initials onto the logo plate for when no logo is set.
function paintBug() {
  var word = document.getElementById('f3');
  var now = document.querySelector('.corner-bug-now');
  if (now) now.textContent = word ? (word.textContent || '') : '';
  if (now && now.parentNode) now.parentNode.style.display = /\\S/.test(now.textContent || '') ? '' : 'none';
  var show = document.getElementById('f1');
  var row = document.querySelector('.corner-bug-row');
  if (row) row.classList.toggle('corner-bug-empty', !(show && /\\S/.test(show.textContent || '')));
  var name = document.getElementById('f0');
  var mono = document.querySelector('.corner-bug-mono');
  if (mono) {
    var words = String(name ? name.textContent : '').replace(/^\\s+|\\s+$/g, '').split(/\\s+/);
    var initials = '';
    for (var i = 0; i < words.length && initials.length < 2; i++) {
      if (words[i]) initials += words[i].charAt(0).toUpperCase();
    }
    mono.textContent = initials;
  }
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', paintBug);
else paintBug();
'''
